<style>
.rss-workspace{display:flex;flex-direction:column;gap:20px;min-width:0}.rss-workspace p{line-height:1.6}.rss-muted{font-size:12px;color:var(--theme-muted-text-color)}.rss-toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:14px;background:var(--theme-surface-base);border:1px solid var(--theme-border-color);border-radius:12px}.rss-toolbar>div:first-child{flex:1;min-width:180px}.rss-toolbar>div:nth-child(2){min-width:160px}.rss-summary{display:flex;gap:20px;flex-wrap:wrap;font-size:12px;color:var(--theme-muted-text-color)}.rss-summary strong{font-size:17px;color:var(--theme-header-text-color);margin-right:5px}.rss-list{display:flex;flex-direction:column;gap:12px}.rss-row{padding:18px 20px;border:1px solid var(--theme-card-border-color);border-radius:12px;background:var(--theme-surface-base);min-width:0}.rss-row-top{display:flex;align-items:flex-start;gap:12px}.rss-icon{width:36px;height:36px;display:grid;place-items:center;border-radius:9px;background:var(--theme-surface-subtle);color:var(--theme-accent);flex-shrink:0}.rss-title{flex:1;min-width:0}.rss-title h2{font-size:15px;font-weight:600}.rss-title a{color:var(--theme-header-text-color)}.rss-title p{font-size:12px;color:var(--theme-muted-text-color);overflow-wrap:anywhere;margin-top:3px}.rss-badge{font-size:10px;font-weight:600;border-radius:6px;padding:4px 8px;background:var(--theme-surface-soft);color:var(--theme-muted-text-color);white-space:nowrap}.rss-badge[data-tone=warning]{background:rgba(217,119,6,.10);color:var(--theme-warning-color,#b45309)}.rss-badge[data-tone=success]{color:var(--theme-accent);background:rgba(var(--theme-accent-rgb),.09)}.rss-row-meta{display:grid;grid-template-columns:1fr 1.2fr 1.2fr 1fr;gap:18px;margin:16px 0;padding:14px 0;border-top:1px solid var(--theme-divider-border-color);border-bottom:1px solid var(--theme-divider-border-color);font-size:12px}.rss-row-meta dt{font-size:11px;color:var(--theme-muted-text-color);margin-bottom:4px}.rss-row-meta dd{overflow-wra